// page/i18n.js — language state and UI-chrome translation.
//
// The page sandbox cannot import modules, so this is a classic script that
// installs a small global. Dynamic content generated by view.js already has
// English strings; this file covers static HTML and the remaining hardcoded
// chrome. Conversation text (diff panes, lab input/output) is never touched:
// those nodes carry data-no-i18n or live inside an excluded container.
(function () {
  "use strict"

  var KEY = "compress-core.lang"

  function normalize(value) {
    value = String(value || "").toLowerCase()
    return value.indexOf("zh") === 0 ? "zh" : "en"
  }

  function saved() {
    try {
      return localStorage.getItem(KEY)
    } catch (err) {
      return null
    }
  }

  // 默认中文。宿主把插件页塞进 sandbox="allow-scripts" 的 iframe（magpie 没有给
  // allow-same-origin），localStorage 读写都会抛，面板上的选择存不住；navigator.language
  // 跟着宿主走，也不是操作员的偏好。所以没有存储时只能写死 zh。
  var initial = saved()
  var lang = normalize(initial || "zh")

  var TEXT_EN = {
    // page chrome / static HTML
    "压缩": "Compression",
    "最近": "Recent",
    "网关请求压缩 · 本地引擎 · 不耗 token": "Gateway request compression · local engines · no token cost",
    "保存": "Save",
    "装 retrieve": "Install retrieve",
    "压缩流水线 · 串行执行，各司其职": "Compression pipeline · serial, each engine does its job",
    "请求按编号依次经过策略；每步只处理自己认领的内容，失败仅回滚该步。未启用的策略不会运行，LeanCTX 位于结构化数据之后、通用散文剪枝之前。": "Requests pass through the strategies in order. Each step handles only its own content, and a failure rolls back only that step. Disabled strategies do not run; LeanCTX sits after structured-data handling and before general prose pruning.",
    "已处理会话": "Processed sessions",
    "清空会话": "Clear sessions",
    "清空日志": "Clear logs",
    "暂无记录。打开下面的「记录完整对话快照」后，每条请求都会在这里留一条。": "No records yet. Turn on “Record full conversation snapshots” below and every request will leave a row here.",
    "暂无记录。记录已打开，下一条经过网关的请求就会出现在这里，保留最新 {n} 条。": "No records yet. Recording is on; the next request through the gateway appears here. The newest {n} are kept.",
    "返回": "Back",
    "自定义策略": "Custom strategies",
    "高级设置": "Advanced settings",
    "压缩预算（毫秒）": "Compression budget (ms)",
    "单次请求允许的最大压缩耗时": "Maximum compression time per request",
    "保留系统消息": "Keep system messages",
    "系统提示词不参与压缩": "The system prompt is not compressed",
    "保留最近轮数": "Keep recent turns",
    "最近 N 轮对话不参与压缩；开大它，前缀缓存会每轮 miss（默认 0）": "The newest N turns are not compressed; raising it makes the prefix cache miss every turn (default 0)",
    "记录完整对话快照": "Record full conversation snapshots",
    "开启后每次请求把完整原文写到磁盘并在页面留副本（含隐私内容），默认关闭": "When on, every request writes the full text to disk and leaves a copy for the page (contains private content); off by default",
    "实验室": "Lab",
    "本地运行 · 不耗 token": "Runs locally · no token cost",
    "输入": "Input",
    "输入形态": "Input type",
    "纯文本（当成一条 user 消息）": "Plain text (treated as one user message)",
    "请求体 JSON（工具输出、重复块）": "Request body JSON (tool output, repeated blocks)",
    "选择策略": "Choose a strategy",
    "输入原文": "Input text",
    "大部分策略靠上下文——同一会话里已经发过的重复内容、工具输出、多轮历史，或者特定协议。能直接压单段文本的只有少数几个（lite、caveman、ultra、aggressive、headroom），而且各只去掉一类东西：行尾空白、客套话、语气词、冗余结构、可折叠的 JSON 数组。文本太短，多半显示「没命中」，那是正常结果，不是坏了。要看真实效果，把「输入形态」切成「请求体 JSON」再贴一条真请求。": "Most strategies need context: repeated text already sent in the same session, tool output, multi-turn history, or a specific protocol. Only a few can compress a single block directly (lite, caveman, ultra, aggressive, headroom), and each removes one kind of thing: trailing whitespace, pleasantries, filler words, redundant structure, or foldable JSON arrays. Short text will usually report “no hit”; that is a normal result, not a fault. To see the real effect, switch “Input type” to “Request body JSON” and paste a real request.",
    "运行试压": "Run test",
    "运行试压后": "After running a test",
    "这里显示压缩前后的对比": "the before/after comparison appears here",
    "压缩前后差异": "Before & after",
    // dynamic chrome / reason text
    "请求": "request",
    "(未知模型)": "(unknown model)",
    "仅摘要": "summary only",
    "全文": "full text",
    "策略贡献": "Strategy contributions",
    "这次请求没有任何策略被启用。": "No strategy was enabled for this request.",
    "命中": "hit",
    "跳过": "skipped",
    "压缩前": "Before",
    "压缩后": "After",
    "压缩率": "Rate",
    "节省": "Saved",
    "正在加载完整快照…": "Loading the full snapshot…",
    "没改动": "no change",
    "输入里没有重复出现的块——去重要靠同一会话里已经发过的文本。": "No repeated block in the input — deduplication relies on text already sent earlier in the same session.",
    "输入里没有多余空白、重复行或可以精简的工具输出。": "No extra whitespace, repeated lines, or compactable tool output in the input.",
    "输入里没有识别到命令输出——这个策略只处理工具结果。": "No command output recognized — this strategy only handles tool results.",
    "没有够大的 JSON 数组可折叠，或者压完反而更大。": "No JSON array large enough to fold, or the result is not smaller.",
    "这条请求里没有 Responses 协议的 shell / patch / search 工具输出。": "No Responses-protocol shell / patch / search output in this request.",
    "这个策略只对 Responses 协议生效，实验室目前按 chat 跑。": "This strategy only applies to the Responses protocol; the lab currently runs chat.",
    "超出了这次试压的时间预算。": "This test exceeded its time budget.",
    "压完还原不回去，已按 fail-open 回滚。": "The result could not be restored, so it was rolled back (fail-open).",
    "策略内部报错，已按 fail-open 回滚。": "The strategy errored and was rolled back (fail-open).",
    "这个策略在当前环境里跑不了。": "This strategy cannot run in this environment.",
    "这次没启用这个策略。": "This strategy was not enabled for this test.",
    "改动了。": "changed.",
    "请输入要试压的文本": "Enter some text to compress",
    "试压引擎未加载": "Lab engine not loaded",
    "正在运行…": "Running…",
    "输入里没有它要的东西": "nothing in the input matches what it looks for",
    "依赖未配置": "dependency not configured",
    "未启用": "not enabled",
    "有改动": "changed",
    "不可用": "unavailable",
    "没有可折叠的重复块": "no repeatable block to fold",
    "扫过了：这段文本里没有它能去掉的东西": "scanned: nothing in this text it can remove",
    "没有可清理的空白或工具输出": "no whitespace or tool output to clean",
    "没有可压缩的 JSON，或压缩后不更小": "no compressible JSON, or not smaller after compression",
    "超出时间预算": "over the time budget",
    "出错后放行": "errored, passed through",
    "调用方没声明 retrieve 工具（ccr 门控，不是故障）": "caller declared no retrieve tool (ccr gate, not a fault)",
    "没有匹配上的工具输出": "no matching tool output",
    "不是 responses 协议": "not the responses protocol",
    "没有可压缩的响应项": "no compressible response item",
    "还原校验没过，已整包回退": "round-trip check failed, whole body reverted",
    "body 超过尺寸上限，原样放行": "body over the size cap, passed through",
    "引擎出错，已回退": "engine error, reverted",
    "再点一次确认": "Click again to confirm",
    "已提交，下一次本地请求时执行": "Submitted — runs on the next local request",
    "已提交，下个请求执行": "Submitted — runs on the next request",
    "retrieve 工具已装好": "retrieve tool installed",
    "安装失败，点击重试": "Install failed — click to retry",
    "安装 retrieve 工具": "Install retrieve tool",
    "已保存并生效": "Saved and applied",
    "保存失败": "Could not save options",
    "读不到配置": "Could not read options",
    "渲染失败：": "Render failed: ",
    "这条记录的完整快照没有随页面发布（可能已被清理或超过发布上限），只剩索引里的体积、模型与协议。": "The full snapshot for this record was not published with the page (it may have been cleaned up or exceeded the publish cap); only the size, model, and protocol from the index are left.",
    "窗口外还有 0 行完全一致的内容未显示。": "No identical lines outside the window are hidden."
  }

  // These are exact attributes used by the static HTML.
  var ATTR_EN = {
    "立即保存并生效": "Save and apply now",
    "把 omniroute_ccr_retrieve 装进 agent：ccr 换出的原文靠它取回": "Install omniroute_ccr_retrieve into the agent; it is how ccr markers get their original text back",
    "自定义策略": "Custom strategies",
    "查看压缩流水线": "View the compression pipeline",
    "实验室": "Lab",
    "删掉已处理的会话快照（含对话原文），不可恢复": "Delete processed conversation snapshots (including the original text); this cannot be undone",
    "删掉 requests.jsonl 的两代文件，并把累计计数归零": "Delete both generations of requests.jsonl and reset the cumulative counters",
    "粘贴一段对话或文本…": "Paste a conversation or some text…"
  }

  var originals = new WeakMap()
  var attrOriginals = new WeakMap()
  var observer = null
  var listeners = []

  function excluded(node) {
    var el = node.nodeType === 1 ? node : node.parentNode
    while (el && el !== document.body) {
      if (el.hasAttribute && el.hasAttribute("data-no-i18n")) return true
      if (el.classList && (el.classList.contains("diff-pane-body") || el.classList.contains("lab-input"))) return true
      if (el.tagName === "SCRIPT" || el.tagName === "STYLE" || el.tagName === "TEXTAREA" || el.tagName === "PRE" || el.tagName === "CODE") return true
      el = el.parentNode
    }
    return false
  }

  function translateTextNode(node) {
    if (!node || node.nodeType !== 3 || excluded(node)) return
    if (lang !== "en") {
      if (originals.has(node)) {
        node.nodeValue = originals.get(node)
        originals.delete(node)
      }
      return
    }
    var raw = node.nodeValue
    var trimmed = raw.trim()
    if (!trimmed || !/[一-鿿]/.test(trimmed)) return
    var en = TEXT_EN[trimmed]
    if (!en) return
    var start = raw.indexOf(trimmed)
    if (!originals.has(node)) originals.set(node, raw)
    var next = raw.slice(0, start) + en + raw.slice(start + trimmed.length)
    if (next !== raw) node.nodeValue = next
  }

  function translateAttrs(el) {
    if (!el || el.nodeType !== 1) return
    if (el.tagName !== "TEXTAREA" && excluded(el)) return
    if (!attrOriginals.has(el)) attrOriginals.set(el, {})
    var savedAttrs = attrOriginals.get(el)
    ;["title", "placeholder", "aria-label"].forEach(function (name) {
      if (lang !== "en") {
        if (name in savedAttrs) {
          el.setAttribute(name, savedAttrs[name])
          delete savedAttrs[name]
        }
        return
      }
      var value = el.getAttribute(name)
      if (value == null || !/[一-鿿]/.test(value)) return
      var en = ATTR_EN[value.trim()]
      if (!en) return
      if (!(name in savedAttrs)) savedAttrs[name] = value
      el.setAttribute(name, en)
    })
  }

  function walk(root) {
    if (root && root.nodeType === 1 && root.tagName === "TEXTAREA") {
      translateAttrs(root)
      return
    }
    if (!root || excluded(root)) return
    if (root.nodeType === 3) {
      translateTextNode(root)
      return
    }
    if (root.nodeType !== 1) return
    translateAttrs(root)
    var child = root.firstChild
    while (child) {
      walk(child)
      child = child.nextSibling
    }
  }

  function apply(root) {
    var target = root || document.body
    if (!target) return
    if (document.documentElement) document.documentElement.lang = lang === "zh" ? "zh-CN" : "en"
    walk(target)
    var toggle = document.querySelector("[data-lang-toggle]")
    if (toggle) {
      toggle.textContent = lang === "zh" ? "EN" : "中文"
      toggle.setAttribute("aria-label", lang === "zh" ? "Switch to English" : "Switch to Chinese")
      toggle.setAttribute("title", lang === "zh" ? "Switch to English" : "Switch to Chinese")
    }
  }

  function stopObserver() {
    if (observer) {
      observer.disconnect()
      observer = null
    }
  }

  function startObserver() {
    if (observer || typeof MutationObserver === "undefined" || !document.body) return
    observer = new MutationObserver(function (records) {
      if (lang !== "en") return
      records.forEach(function (record) {
        if (record.type === "characterData") translateTextNode(record.target)
        else if (record.type === "attributes") translateAttrs(record.target)
        else if (record.type === "childList") {
          for (var i = 0; i < record.addedNodes.length; i++) walk(record.addedNodes[i])
        }
      })
    })
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      characterData: true,
      attributes: true,
      attributeFilter: ["title", "placeholder", "aria-label"],
    })
  }

  function setLang(next) {
    var value = normalize(next)
    if (value === lang) return
    lang = value
    try { localStorage.setItem(KEY, lang) } catch (err) { /* private mode */ }
    stopObserver()
    apply(document.body)
    if (lang === "en") startObserver()
    listeners.forEach(function (fn) {
      try { fn(lang) } catch (err) { /* a listener must not break the toggle */ }
    })
  }

  function toggle() {
    setLang(lang === "zh" ? "en" : "zh")
  }

  if (typeof window !== "undefined" && window.addEventListener) {
    window.addEventListener("storage", function (event) {
      if (event && event.key === KEY && event.newValue) setLang(event.newValue)
    })
  }

  function makeToggle() {
    var host = document.querySelector(".preset-group") || document.querySelector(".main-head")
    if (!host) return
    var btn = document.createElement("button")
    btn.type = "button"
    btn.className = "save-btn lang-toggle"
    btn.setAttribute("data-lang-toggle", "")
    btn.textContent = lang === "zh" ? "EN" : "中文"
    btn.setAttribute("aria-label", lang === "zh" ? "Switch to English" : "Switch to Chinese")
    btn.setAttribute("title", lang === "zh" ? "Switch to English" : "Switch to Chinese")
    btn.addEventListener("click", toggle)
    host.append(btn)
  }

  function pick(zh, en) {
    return lang === "zh" ? zh : en
  }

  function onChange(fn) {
    if (typeof fn === "function") listeners.push(fn)
  }

  globalThis.CompressI18n = {
    get lang() { return lang },
    isZh: function () { return lang === "zh" },
    normalize: normalize,
    pick: pick,
    t: function (text) { return lang === "zh" ? text : (TEXT_EN[String(text || "").trim()] || text) },
    apply: apply,
    setLang: setLang,
    toggle: toggle,
    onChange: onChange,
    TEXT_EN: TEXT_EN,
    ATTR_EN: ATTR_EN,
  }

  if (typeof document !== "undefined") {
    makeToggle()
    apply(document.body)
    if (lang === "en") startObserver()
  }
})()